-- MySMS PostgreSQL schema. Generated from the MySMS schema specification; do not edit by hand.

-- Module: iam — Identity & Access

CREATE SCHEMA IF NOT EXISTS iam;
COMMENT ON SCHEMA iam IS 'Identity & Access: Login accounts, roles, permissions, scoped role grants, tokens and devices. A person (people.person) may own one account per tenant.';


CREATE TABLE iam.user_account (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    person_id uuid,
    username varchar(150),
    email varchar(320),
    mobile_no varchar(20),
    password_hash text,
    status varchar(30) NOT NULL DEFAULT  'active',
    email_verified_at timestamptz,
    mobile_verified_at timestamptz,
    must_reset_password boolean NOT NULL DEFAULT false,
    referred_by_user_id uuid,
    terms_accepted_at timestamptz,
    locale varchar(10),
    timezone varchar(64),
    last_login_at timestamptz,
    account_expires_at timestamptz,
    failed_login_count integer NOT NULL DEFAULT 0,
    locked_until timestamptz,
    last_login_role_id uuid,
    registered_at timestamptz,
    joined_on date,
    external_ref varchar(100),
    signature text,
    use_signature boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    user_type varchar(40),
    CONSTRAINT pk_user_account PRIMARY KEY (id),
    CONSTRAINT ck_user_account_status CHECK (status IN ('active', 'inactive', 'locked', 'exited')),
    CONSTRAINT ck_user_account_1 CHECK (username IS NOT NULL OR email IS NOT NULL OR mobile_no IS NOT NULL),
    CONSTRAINT ck_user_account_user_type CHECK (user_type IN ('admin', 'teacher', 'student', 'guardian', 'staff', 'librarian', 'accountant', 'alumni')),
    CONSTRAINT uq_user_account_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE iam.user_account IS 'A login account. Holds credentials and verification state only; personal data lives in people.person.';
COMMENT ON COLUMN iam.user_account.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.user_account.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.user_account.person_id IS 'Person this account belongs to (NULL for service accounts).';
COMMENT ON COLUMN iam.user_account.username IS 'Login name, unique per tenant ignoring case (optional when the user logs in by e-mail or mobile).';
COMMENT ON COLUMN iam.user_account.email IS 'Login / notification e-mail, unique per tenant ignoring case.';
COMMENT ON COLUMN iam.user_account.mobile_no IS 'Login / notification mobile number.';
COMMENT ON COLUMN iam.user_account.password_hash IS 'Password hash (argon2/bcrypt); NULL for SSO-only accounts.';
COMMENT ON COLUMN iam.user_account.status IS 'Account state.';
COMMENT ON COLUMN iam.user_account.email_verified_at IS 'When the e-mail was verified.';
COMMENT ON COLUMN iam.user_account.mobile_verified_at IS 'When the mobile number was verified.';
COMMENT ON COLUMN iam.user_account.must_reset_password IS 'Force a password change at next login.';
COMMENT ON COLUMN iam.user_account.referred_by_user_id IS 'Account that created / referred this account.';
COMMENT ON COLUMN iam.user_account.terms_accepted_at IS 'When the user accepted the terms of use.';
COMMENT ON COLUMN iam.user_account.locale IS 'Preferred UI locale.';
COMMENT ON COLUMN iam.user_account.timezone IS 'Preferred time zone.';
COMMENT ON COLUMN iam.user_account.last_login_at IS 'Last successful login.';
COMMENT ON COLUMN iam.user_account.account_expires_at IS 'Account stops working after this time (fixed-term students, guests).';
COMMENT ON COLUMN iam.user_account.failed_login_count IS 'Consecutive failed sign-ins (lock-out after the configured limit).';
COMMENT ON COLUMN iam.user_account.locked_until IS 'Sign-in is refused until this time after repeated failures (progressive lockout); NULL = not locked out. Independent of status locked, which only an administrator lifts.';
COMMENT ON COLUMN iam.user_account.last_login_role_id IS 'Role the user last worked in (restored at next sign-in).';
COMMENT ON COLUMN iam.user_account.registered_at IS 'Self-registration time.';
COMMENT ON COLUMN iam.user_account.joined_on IS 'Date the user joined the institution.';
COMMENT ON COLUMN iam.user_account.external_ref IS 'External system reference (SIS / HR integration key).';
COMMENT ON COLUMN iam.user_account.signature IS 'Signature appended to discussion posts.';
COMMENT ON COLUMN iam.user_account.use_signature IS 'Append the signature by default.';
COMMENT ON COLUMN iam.user_account.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.user_account.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_account.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.user_account.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_account.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.user_account.row_version IS 'Optimistic-locking version.';
COMMENT ON COLUMN iam.user_account.user_type IS 'Default persona hint used for routing after login. Never used for authorisation: permissions come only from roles.';
CREATE UNIQUE INDEX ix_user_account_1 ON iam.user_account (tenant_id, lower(username)) WHERE (username IS NOT NULL AND deleted_at IS NULL);
CREATE UNIQUE INDEX ix_user_account_2 ON iam.user_account (tenant_id, person_id) WHERE (person_id IS NOT NULL AND deleted_at IS NULL);
CREATE UNIQUE INDEX ix_user_account_3 ON iam.user_account (tenant_id, lower(email)) WHERE (email IS NOT NULL AND deleted_at IS NULL);
CREATE UNIQUE INDEX ix_user_account_4 ON iam.user_account (tenant_id, mobile_no) WHERE (mobile_no IS NOT NULL);

CREATE TABLE iam.role (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    code varchar(80) NOT NULL,
    display_name varchar(120),
    description text,
    is_system boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    authority_level integer,
    parent_role_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_role PRIMARY KEY (id),
    CONSTRAINT uq_role_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE iam.role IS 'Named set of permissions. NULL tenant = platform-defined role available to every tenant.';
COMMENT ON COLUMN iam.role.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.role.tenant_id IS 'Owning tenant (customer organisation). Every role row belongs to one tenant; platform role templates are copied into each tenant at provisioning. Row-level security key.';
COMMENT ON COLUMN iam.role.code IS 'Role code, e.g. principal, class_teacher, lms_course_creator, lms_evaluator.';
COMMENT ON COLUMN iam.role.display_name IS 'Display name.';
COMMENT ON COLUMN iam.role.description IS 'Purpose of the role.';
COMMENT ON COLUMN iam.role.is_system IS 'Platform-managed role that tenants cannot edit.';
COMMENT ON COLUMN iam.role.is_active IS 'Role can be granted.';
COMMENT ON COLUMN iam.role.authority_level IS 'Rank used to decide which roles a user may grant or manage (lower = more authority).';
COMMENT ON COLUMN iam.role.parent_role_id IS 'Parent role (inherits its permissions).';
COMMENT ON COLUMN iam.role.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.role.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.role.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.role.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.role.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.role.row_version IS 'Optimistic-locking version.';

CREATE TABLE iam.permission (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    code varchar(120) NOT NULL,
    display_name varchar(150),
    description text,
    module_code varchar(50),
    is_navigation boolean NOT NULL DEFAULT false,
    is_modifiable boolean NOT NULL DEFAULT true,
    applies_to_all_roles boolean NOT NULL DEFAULT false,
    is_object_level boolean NOT NULL DEFAULT false,
    retired_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_permission PRIMARY KEY (id),
    CONSTRAINT uq_permission_code UNIQUE (code)
);
COMMENT ON TABLE iam.permission IS 'Atomic permission checked by the application.';
COMMENT ON COLUMN iam.permission.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.permission.code IS 'Permission code, e.g. attendance.record.write.';
COMMENT ON COLUMN iam.permission.display_name IS 'Display name.';
COMMENT ON COLUMN iam.permission.description IS 'Explanation.';
COMMENT ON COLUMN iam.permission.module_code IS 'Owning module (schema name).';
COMMENT ON COLUMN iam.permission.is_navigation IS 'Permission also controls a navigation menu entry.';
COMMENT ON COLUMN iam.permission.is_modifiable IS 'Tenants may grant / revoke it (false = fixed).';
COMMENT ON COLUMN iam.permission.applies_to_all_roles IS 'Granted to every role implicitly.';
COMMENT ON COLUMN iam.permission.is_object_level IS 'Checked per record (e.g. own submissions) rather than globally.';
COMMENT ON COLUMN iam.permission.retired_at IS 'When no live operation callable by tenant users carried the code any more (iam.api_permission); never deleted. NULL = published.';
COMMENT ON COLUMN iam.permission.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.permission.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.permission.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.permission.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.permission.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.permission.row_version IS 'Optimistic-locking version.';

CREATE TABLE iam.api_permission (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    module_code varchar(50) NOT NULL,
    operation_id varchar(150) NOT NULL,
    http_method varchar(10) NOT NULL,
    path_template varchar(300) NOT NULL,
    permission_code varchar(120) NOT NULL,
    schemes varchar(120) NOT NULL,
    is_anonymous boolean NOT NULL DEFAULT false,
    audience varchar(20) NOT NULL,
    release varchar(60) NOT NULL,
    catalogue_sha256 varchar(64) NOT NULL,
    first_seen_at timestamptz NOT NULL,
    last_seen_at timestamptz NOT NULL,
    retired_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_api_permission PRIMARY KEY (id),
    CONSTRAINT ck_api_permission_http_method CHECK (http_method IN ('GET', 'POST', 'PUT', 'PATCH', 'DELETE')),
    CONSTRAINT ck_api_permission_audience CHECK (audience IN ('public', 'internal', 'platform'))
);
COMMENT ON TABLE iam.api_permission IS 'Every operation of every deployed module with the permission guarding it, as each module publishes its catalogue at start-up (JAVA-CODING-RULES 16.2). Platform-level: no tenant, no row-level security; read by platform staff only.';
COMMENT ON COLUMN iam.api_permission.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.api_permission.module_code IS 'Publishing module (schema name).';
COMMENT ON COLUMN iam.api_permission.operation_id IS 'Contract operation id, e.g. iam.ListPermissions.';
COMMENT ON COLUMN iam.api_permission.http_method IS 'HTTP method of the operation.';
COMMENT ON COLUMN iam.api_permission.path_template IS 'Path template of the operation, e.g. /v1/iam/permissions/{permissionId}.';
COMMENT ON COLUMN iam.api_permission.permission_code IS 'Permission code (x-permission) guarding the operation.';
COMMENT ON COLUMN iam.api_permission.schemes IS 'Security schemes whose tokens may call it, space-separated (bearerAuth, platformAdminAuth).';
COMMENT ON COLUMN iam.api_permission.is_anonymous IS 'The operation may also be called without a token.';
COMMENT ON COLUMN iam.api_permission.audience IS 'Who may call it: public (people), internal (MySMS services), platform (platform staff).';
COMMENT ON COLUMN iam.api_permission.release IS 'Release of the module that last published the operation.';
COMMENT ON COLUMN iam.api_permission.catalogue_sha256 IS 'SHA-256 of the module catalogue that last published the operation.';
COMMENT ON COLUMN iam.api_permission.first_seen_at IS 'When a catalogue first carried the operation.';
COMMENT ON COLUMN iam.api_permission.last_seen_at IS 'When a catalogue last carried the operation.';
COMMENT ON COLUMN iam.api_permission.retired_at IS 'When the operation was retired: no catalogue carried it for mysms.iam.api-permission.retire-after; NULL = published.';
COMMENT ON COLUMN iam.api_permission.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.api_permission.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.api_permission.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.api_permission.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.api_permission.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.api_permission.row_version IS 'Optimistic-locking version.';
CREATE UNIQUE INDEX uq_api_permission_operation_id ON iam.api_permission (operation_id) WHERE deleted_at IS NULL;
CREATE INDEX ix_api_permission_module_code ON iam.api_permission (module_code);
CREATE INDEX ix_api_permission_permission_code ON iam.api_permission (permission_code);

CREATE TABLE iam.setting_definition (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    setting_key varchar(100) NOT NULL,
    category varchar(60) NOT NULL,
    value_type varchar(20) NOT NULL,
    allowed_values varchar(60)[],
    min_value integer,
    max_value integer,
    default_value varchar(500),
    allowed_scopes varchar(20)[] NOT NULL,
    user_editable boolean NOT NULL DEFAULT true,
    description text,
    sort_order integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_setting_definition PRIMARY KEY (id),
    CONSTRAINT uq_setting_definition_setting_key UNIQUE (setting_key),
    CONSTRAINT ck_setting_definition_value_type CHECK (value_type IN ('string', 'boolean', 'integer', 'choice')),
    CONSTRAINT ck_setting_definition_choice CHECK ((value_type = 'choice') = (allowed_values IS NOT NULL)),
    CONSTRAINT ck_setting_definition_range CHECK (min_value IS NULL OR max_value IS NULL OR min_value <= max_value),
    CONSTRAINT ck_setting_definition_scopes CHECK (allowed_scopes <@ ARRAY['tenant', 'institution', 'department', 'class_section', 'user']::varchar(20)[] AND cardinality(allowed_scopes) > 0)
);
COMMENT ON TABLE iam.setting_definition IS 'Product catalogue of settings (theme, density, language...): type, allowed values, default and the scopes a value may be set at. Global: no tenant; maintained by migrations.';
COMMENT ON COLUMN iam.setting_definition.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.setting_definition.setting_key IS 'Stable key, e.g. ui.theme.';
COMMENT ON COLUMN iam.setting_definition.category IS 'Grouping on the settings screens, e.g. appearance.';
COMMENT ON COLUMN iam.setting_definition.value_type IS 'Type of the value: string, boolean, integer or choice.';
COMMENT ON COLUMN iam.setting_definition.allowed_values IS 'Allowed values of a choice setting.';
COMMENT ON COLUMN iam.setting_definition.min_value IS 'Smallest allowed value of an integer setting.';
COMMENT ON COLUMN iam.setting_definition.max_value IS 'Largest allowed value of an integer setting.';
COMMENT ON COLUMN iam.setting_definition.default_value IS 'Value when no scope sets one.';
COMMENT ON COLUMN iam.setting_definition.allowed_scopes IS 'Scopes at which a value may be set (subset of tenant, institution, department, class_section, user).';
COMMENT ON COLUMN iam.setting_definition.user_editable IS 'Whether users may set the setting for themselves.';
COMMENT ON COLUMN iam.setting_definition.description IS 'What the setting changes.';
COMMENT ON COLUMN iam.setting_definition.sort_order IS 'Display order within its category.';
COMMENT ON COLUMN iam.setting_definition.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.setting_definition.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.setting_definition.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.setting_definition.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.setting_definition.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.setting_definition.row_version IS 'Optimistic-locking version.';

