CREATE TABLE iam.user_role (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role_id uuid NOT NULL,
    scope_type varchar(30) NOT NULL DEFAULT  'tenant',
    scope_id uuid,
    valid_from date,
    valid_to date,
    is_active boolean NOT NULL DEFAULT true,
    is_primary boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_user_role PRIMARY KEY (id),
    CONSTRAINT ck_user_role_scope_type CHECK (scope_type IN ('tenant', 'institution', 'department', 'class_section', 'course', 'lms_course', 'lms_cohort')),
    CONSTRAINT ck_user_role_1 CHECK ((scope_type = 'tenant') = (scope_id IS NULL))
);
COMMENT ON TABLE iam.user_role IS 'Role granted to an account, optionally limited to a scope (institution, class section, department, LMS course...).';
COMMENT ON COLUMN iam.user_role.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.user_role.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.user_role.user_id IS 'Account receiving the role.';
COMMENT ON COLUMN iam.user_role.role_id IS 'Role granted.';
COMMENT ON COLUMN iam.user_role.scope_type IS 'Scope kind the grant is limited to.';
COMMENT ON COLUMN iam.user_role.scope_id IS 'Polymorphic scope record id (NULL when scope_type = tenant).';
COMMENT ON COLUMN iam.user_role.valid_from IS 'Grant start.';
COMMENT ON COLUMN iam.user_role.valid_to IS 'Grant end.';
COMMENT ON COLUMN iam.user_role.is_active IS 'Grant currently in force (can be suspended without deleting).';
COMMENT ON COLUMN iam.user_role.is_primary IS 'The grant whose scope is the user''s primary unit of its type (at most one per user and scope type); settings resolve through the primary department.';
COMMENT ON COLUMN iam.user_role.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.user_role.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_role.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.user_role.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_role.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.user_role.row_version IS 'Optimistic-locking version.';

CREATE TABLE iam.user_permission (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
