COMMENT ON COLUMN iam.user_permission.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.user_permission.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.user_permission.user_id IS 'Account.';
COMMENT ON COLUMN iam.user_permission.permission_id IS 'Permission.';
COMMENT ON COLUMN iam.user_permission.effect IS 'Whether the permission is added or removed.';
COMMENT ON COLUMN iam.user_permission.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.user_permission.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_permission.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.user_permission.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_permission.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.user_permission.row_version IS 'Optimistic-locking version.';

CREATE TABLE iam.tenant_authz_version (
    tenant_id uuid NOT NULL,
    authz_version bigint NOT NULL DEFAULT 1,
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_tenant_authz_version PRIMARY KEY (tenant_id),
    CONSTRAINT ck_tenant_authz_version_authz_version CHECK (authz_version > 0)
);
COMMENT ON TABLE iam.tenant_authz_version IS 'Counter raised whenever a change in the tenant (iam.role, iam.role_permission, iam.user_role, iam.user_permission) can change what somebody may do. Access tokens carry the value, and each service''s permissions filter refetches its role-to-permission cache when a caller''s token is newer than what it cached. Carries no audit set: the changes that raise it are audited where they happen.';
COMMENT ON COLUMN iam.tenant_authz_version.tenant_id IS 'Owning tenant (customer organisation). Row-level security key, and the whole key of the row.';
COMMENT ON COLUMN iam.tenant_authz_version.authz_version IS 'Raised by one per change; a token carrying a lower value was issued before that change.';
COMMENT ON COLUMN iam.tenant_authz_version.updated_at IS 'When the version was last raised.';

CREATE TABLE iam.user_department_access (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    department_id uuid NOT NULL,
    is_primary boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_user_department_access PRIMARY KEY (id)
);
COMMENT ON TABLE iam.user_department_access IS 'Departments whose data an account may access; one may be marked primary.';
COMMENT ON COLUMN iam.user_department_access.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.user_department_access.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.user_department_access.user_id IS 'Account.';
COMMENT ON COLUMN iam.user_department_access.department_id IS 'Department.';
COMMENT ON COLUMN iam.user_department_access.is_primary IS 'Primary department of the account.';
COMMENT ON COLUMN iam.user_department_access.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.user_department_access.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_department_access.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.user_department_access.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_department_access.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.user_department_access.row_version IS 'Optimistic-locking version.';

CREATE TABLE iam.auth_token (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    token_type varchar(30) NOT NULL,
    name varchar(120),
    token_hash char(64) NOT NULL,
    sent_to varchar(320),
    ip_address inet,
    expires_at timestamptz,
    last_used_at timestamptz,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    scopes varchar(100)[],
    CONSTRAINT pk_auth_token PRIMARY KEY (id),
    CONSTRAINT ck_auth_token_token_type CHECK (token_type IN ('api', 'remember_me', 'one_time_login', 'email_verification', 'mobile_verification', 'password_reset', 'refresh')),
    CONSTRAINT uq_auth_token_token_hash UNIQUE (token_hash)
);
COMMENT ON TABLE iam.auth_token IS 'Hashed credential tokens: API tokens, remember-me, one-time login, verification and password-reset tokens.';
COMMENT ON COLUMN iam.auth_token.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.auth_token.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.auth_token.user_id IS 'Account the token belongs to.';
COMMENT ON COLUMN iam.auth_token.token_type IS 'Purpose of the token.';
COMMENT ON COLUMN iam.auth_token.name IS 'Label for API tokens.';
COMMENT ON COLUMN iam.auth_token.token_hash IS 'SHA-256 of the token; the raw token is never stored.';
COMMENT ON COLUMN iam.auth_token.sent_to IS 'E-mail / phone the token was delivered to.';
COMMENT ON COLUMN iam.auth_token.ip_address IS 'IP that requested the token.';
COMMENT ON COLUMN iam.auth_token.expires_at IS 'Expiry time.';
COMMENT ON COLUMN iam.auth_token.last_used_at IS 'Last use.';
COMMENT ON COLUMN iam.auth_token.revoked_at IS 'When revoked / consumed.';
COMMENT ON COLUMN iam.auth_token.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.auth_token.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.auth_token.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.auth_token.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.auth_token.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.auth_token.row_version IS 'Optimistic-locking version.';
COMMENT ON COLUMN iam.auth_token.scopes IS 'Permission scopes granted to the token (NULL = full access of the user).';
CREATE INDEX ix_auth_token_refresh_family ON iam.auth_token (tenant_id, name) WHERE token_type = 'refresh';
COMMENT ON INDEX iam.ix_auth_token_refresh_family IS 'Refresh tokens of one sign-in session (family id in name): rotation and reuse detection revoke the whole family.';

CREATE TABLE iam.user_device (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    device_identifier text NOT NULL,
    platform varchar(30) NOT NULL,
    push_token text,
    last_seen_at timestamptz,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_user_device PRIMARY KEY (id),
    CONSTRAINT ck_user_device_platform CHECK (platform IN ('android', 'ios', 'web')),
    CONSTRAINT uq_user_device_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE iam.user_device IS 'Registered device / browser for push notifications.';
COMMENT ON COLUMN iam.user_device.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.user_device.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.user_device.user_id IS 'Account.';
COMMENT ON COLUMN iam.user_device.device_identifier IS 'Device / installation identifier.';
COMMENT ON COLUMN iam.user_device.platform IS 'Client platform.';
COMMENT ON COLUMN iam.user_device.push_token IS 'Push-notification token (FCM/APNs/Web Push).';
COMMENT ON COLUMN iam.user_device.last_seen_at IS 'Last activity from this device.';
COMMENT ON COLUMN iam.user_device.is_active IS 'Whether pushes are sent to this device.';
COMMENT ON COLUMN iam.user_device.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.user_device.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_device.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.user_device.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_device.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.user_device.row_version IS 'Optimistic-locking version.';


CREATE TABLE iam.user_preference (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    pref_key varchar(100) NOT NULL,
    pref_value varchar(500),
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_user_preference PRIMARY KEY (id)
);
COMMENT ON TABLE iam.user_preference IS 'Per-user key/value preference (UI and app settings).';
COMMENT ON COLUMN iam.user_preference.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.user_preference.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.user_preference.user_id IS 'User.';
COMMENT ON COLUMN iam.user_preference.pref_key IS 'Preference key.';
COMMENT ON COLUMN iam.user_preference.pref_value IS 'Preference value.';
COMMENT ON COLUMN iam.user_preference.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.user_preference.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_preference.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.user_preference.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_preference.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.user_preference.row_version IS 'Optimistic-locking version.';

CREATE TABLE iam.setting_value (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    scope_type varchar(20) NOT NULL,
    scope_id uuid,
    setting_key varchar(100) NOT NULL,
    value varchar(500) NOT NULL,
    is_locked boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_setting_value PRIMARY KEY (id),
    CONSTRAINT ck_setting_value_scope_type CHECK (scope_type IN ('tenant', 'institution', 'department', 'class_section', 'user')),
    CONSTRAINT ck_setting_value_scope_id CHECK ((scope_type = 'tenant') = (scope_id IS NULL)),
    CONSTRAINT ck_setting_value_user_unlocked CHECK (NOT (scope_type = 'user' AND is_locked))
);
COMMENT ON TABLE iam.setting_value IS 'A setting value at one scope. Effective value for a user: user > class section > primary department > institution > tenant > default, unless a broader scope locks it.';
COMMENT ON COLUMN iam.setting_value.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.setting_value.tenant_id IS 'Owning tenant (platform.tenant; logical, isolation by RLS).';
COMMENT ON COLUMN iam.setting_value.scope_type IS 'Level the value applies to: tenant, institution, department, class_section or user.';
COMMENT ON COLUMN iam.setting_value.scope_id IS 'Institution (org), department (org), class section (academics) or user account (iam) the value applies to; NULL for tenant. Polymorphic like iam.user_role.scope_id.';
COMMENT ON COLUMN iam.setting_value.setting_key IS 'The setting (iam.setting_definition.setting_key).';
COMMENT ON COLUMN iam.setting_value.value IS 'The value, as text in the setting type.';
COMMENT ON COLUMN iam.setting_value.is_locked IS 'Narrower scopes and users cannot override the value (never set on user scope).';
COMMENT ON COLUMN iam.setting_value.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.setting_value.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.setting_value.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.setting_value.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.setting_value.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.setting_value.row_version IS 'Optimistic-locking version.';
CREATE INDEX ix_setting_value_scope ON iam.setting_value (tenant_id, scope_type, scope_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_setting_value_scope_key ON iam.setting_value (tenant_id, scope_type, scope_id, setting_key) NULLS NOT DISTINCT WHERE deleted_at IS NULL;

CREATE TABLE iam.user_session (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    session_ref varchar(128) NOT NULL,
    device_id uuid,
    ip_address inet,
    user_agent varchar(500),
    started_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz,
    ended_at timestamptz,
    impersonator_user_id uuid,
    active_role_id uuid,
    active_scope_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_user_session PRIMARY KEY (id),
    CONSTRAINT uq_user_session_1 UNIQUE (session_ref)
);
COMMENT ON TABLE iam.user_session IS 'Signed-in session of a user on a web browser or mobile device.';
COMMENT ON COLUMN iam.user_session.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.user_session.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.user_session.user_id IS 'User.';
COMMENT ON COLUMN iam.user_session.session_ref IS 'External session identifier (hashed).';
COMMENT ON COLUMN iam.user_session.device_id IS 'Device used.';
COMMENT ON COLUMN iam.user_session.ip_address IS 'Client IP address.';
COMMENT ON COLUMN iam.user_session.user_agent IS 'User agent.';
COMMENT ON COLUMN iam.user_session.started_at IS 'Sign-in time.';
COMMENT ON COLUMN iam.user_session.last_seen_at IS 'Last activity.';
COMMENT ON COLUMN iam.user_session.ended_at IS 'Sign-out / expiry time.';
COMMENT ON COLUMN iam.user_session.impersonator_user_id IS 'Administrator acting as the user in this session (iam.StartImpersonation); NULL for the user''s own sign-in. Such a session has no refresh token and ends with iam.StopImpersonation or its access token''s expiry.';
COMMENT ON COLUMN iam.user_session.active_role_id IS 'Role the session works in after iam.SwitchRole (its tokens carry only the grants of this role); NULL = every role the user holds.';
COMMENT ON COLUMN iam.user_session.active_scope_id IS 'Scope unit of the active role''s grant the session works in; NULL = every grant of the active role.';
COMMENT ON COLUMN iam.user_session.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.user_session.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_session.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.user_session.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_session.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.user_session.row_version IS 'Optimistic-locking version.';

CREATE TABLE iam.tenant_directory (
    tenant_id uuid NOT NULL,
    tenant_code varchar(60) NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'active',
    source_version integer NOT NULL DEFAULT 0,
    synced_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_tenant_directory PRIMARY KEY (tenant_id),
    CONSTRAINT uq_tenant_directory_tenant_code UNIQUE (tenant_code),
    CONSTRAINT ck_tenant_directory_status CHECK (status IN ('active', 'suspended', 'closed'))
);
COMMENT ON TABLE iam.tenant_directory IS 'Local copy of tenant codes and status, kept from platform tenant events (against-DAG, events only) so that sign-in can resolve a tenant code without reading another schema. Holds no personal data; read before a tenant is known, so it carries no row-level security.';
COMMENT ON COLUMN iam.tenant_directory.tenant_id IS 'Tenant (platform.tenant.id; logical, maintained from platform events).';
COMMENT ON COLUMN iam.tenant_directory.tenant_code IS 'Code users type at sign-in.';
COMMENT ON COLUMN iam.tenant_directory.status IS 'Only active tenants can sign in.';
COMMENT ON COLUMN iam.tenant_directory.source_version IS 'platform.tenant row version this entry reflects; an event with an older version is ignored.';
COMMENT ON COLUMN iam.tenant_directory.synced_at IS 'When the row was last updated from a platform event.';

CREATE TABLE iam.member_record (
    tenant_id uuid NOT NULL,
    record_id uuid NOT NULL,
    record_type varchar(20) NOT NULL,
    user_id uuid,
    person_id uuid,
    institution_id uuid,
    is_deleted boolean NOT NULL DEFAULT false,
    source_version integer NOT NULL,
    synced_at timestamptz NOT NULL,
    CONSTRAINT pk_iam_member_record PRIMARY KEY (tenant_id, record_id),
    CONSTRAINT ck_member_record_record_type CHECK (record_type IN ('staff', 'student')),
    CONSTRAINT ck_member_record_source_version CHECK (source_version >= 1)
);
COMMENT ON TABLE iam.member_record IS 'Staff and student records of login accounts and persons, kept from hr.staff and sis.student events so iam.GetMe can name them (Me.staffIds, Me.studentIds) from its own schema.';
COMMENT ON COLUMN iam.member_record.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.member_record.record_id IS 'hr.staff.id or sis.student.id (logical, maintained from their events).';
COMMENT ON COLUMN iam.member_record.record_type IS 'staff (hr.staff) or student (sis.student).';
COMMENT ON COLUMN iam.member_record.user_id IS 'Login account of the record (iam.user_account.id); NULL when it has none.';
COMMENT ON COLUMN iam.member_record.person_id IS 'Person of the record (people.person.id).';
COMMENT ON COLUMN iam.member_record.institution_id IS 'Institution of the record (org.institution.id).';
COMMENT ON COLUMN iam.member_record.is_deleted IS 'The record was deleted in its module; kept so a late event cannot restore it.';
COMMENT ON COLUMN iam.member_record.source_version IS 'Row version of the hr.staff / sis.student row this entry reflects; an event with an older version is ignored.';
COMMENT ON COLUMN iam.member_record.synced_at IS 'When the row was last changed by an event.';
CREATE INDEX ix_member_record_user ON iam.member_record (tenant_id, user_id) WHERE NOT is_deleted AND user_id IS NOT NULL;
CREATE INDEX ix_member_record_person ON iam.member_record (tenant_id, person_id) WHERE NOT is_deleted AND person_id IS NOT NULL;
COMMENT ON INDEX iam.ix_member_record_user IS 'iam.GetMe: the records of the signed-in account.';
COMMENT ON INDEX iam.ix_member_record_person IS 'iam.GetMe: the records of the signed-in person.';

-- Intra-module foreign keys
ALTER TABLE iam.user_account ADD CONSTRAINT fk_user_account_referred_by_user_id FOREIGN KEY (referred_by_user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE SET NULL (referred_by_user_id);
CREATE INDEX ix_user_account_referred_by_user_id ON iam.user_account (referred_by_user_id);
ALTER TABLE iam.user_account ADD CONSTRAINT fk_user_account_last_login_role_id FOREIGN KEY (last_login_role_id, tenant_id) REFERENCES iam.role (id, tenant_id) ON DELETE SET NULL (last_login_role_id);
CREATE INDEX ix_user_account_last_login_role_id ON iam.user_account (last_login_role_id);
ALTER TABLE iam.role ADD CONSTRAINT fk_role_parent_role_id FOREIGN KEY (parent_role_id, tenant_id) REFERENCES iam.role (id, tenant_id) ON DELETE SET NULL (parent_role_id);
CREATE INDEX ix_role_parent_role_id ON iam.role (parent_role_id);
ALTER TABLE iam.role_permission ADD CONSTRAINT fk_role_permission_role_id FOREIGN KEY (role_id, tenant_id) REFERENCES iam.role (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_role_permission_role_id ON iam.role_permission (role_id);
ALTER TABLE iam.role_permission ADD CONSTRAINT fk_role_permission_permission_id FOREIGN KEY (permission_id) REFERENCES iam.permission (id) ON DELETE CASCADE;
CREATE INDEX ix_role_permission_permission_id ON iam.role_permission (permission_id);
ALTER TABLE iam.user_role ADD CONSTRAINT fk_user_role_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_user_role_user_id ON iam.user_role (user_id);
ALTER TABLE iam.user_role ADD CONSTRAINT fk_user_role_role_id FOREIGN KEY (role_id, tenant_id) REFERENCES iam.role (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_user_role_role_id ON iam.user_role (role_id);
ALTER TABLE iam.user_permission ADD CONSTRAINT fk_user_permission_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_user_permission_user_id ON iam.user_permission (user_id);
ALTER TABLE iam.user_permission ADD CONSTRAINT fk_user_permission_permission_id FOREIGN KEY (permission_id) REFERENCES iam.permission (id) ON DELETE CASCADE;
CREATE INDEX ix_user_permission_permission_id ON iam.user_permission (permission_id);
ALTER TABLE iam.user_department_access ADD CONSTRAINT fk_user_department_access_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_user_department_access_user_id ON iam.user_department_access (user_id);
ALTER TABLE iam.auth_token ADD CONSTRAINT fk_auth_token_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_auth_token_user_id ON iam.auth_token (user_id);
ALTER TABLE iam.user_device ADD CONSTRAINT fk_user_device_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_user_device_user_id ON iam.user_device (user_id);
ALTER TABLE iam.user_preference ADD CONSTRAINT fk_user_preference_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_user_preference_user_id ON iam.user_preference (user_id);
ALTER TABLE iam.setting_value ADD CONSTRAINT fk_setting_value_setting_key FOREIGN KEY (setting_key) REFERENCES iam.setting_definition (setting_key) ON DELETE RESTRICT;
CREATE INDEX ix_setting_value_setting_key ON iam.setting_value (setting_key);
ALTER TABLE iam.user_session ADD CONSTRAINT fk_user_session_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_user_session_user_id ON iam.user_session (user_id);
ALTER TABLE iam.user_session ADD CONSTRAINT fk_user_session_device_id FOREIGN KEY (device_id, tenant_id) REFERENCES iam.user_device (id, tenant_id) ON DELETE SET NULL (device_id);
CREATE INDEX ix_user_session_device_id ON iam.user_session (device_id);

-- === P0-04 / P1-30 / E34: per-tenant roles, MFA, imported credentials ===

CREATE TABLE iam.mfa_credential (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    credential_type varchar(20) NOT NULL,
    label varchar(100),
    secret_enc text NOT NULL,
    verified_at timestamptz,
    last_used_at timestamptz,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_mfa_credential PRIMARY KEY (id),
    CONSTRAINT ck_mfa_credential_type CHECK (credential_type IN ('totp', 'sms', 'email', 'recovery_codes'))
);
COMMENT ON TABLE iam.mfa_credential IS 'Second-factor credential enrolled by a user (TOTP app, SMS/email OTP target, recovery codes).';
COMMENT ON COLUMN iam.mfa_credential.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.mfa_credential.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.mfa_credential.user_id IS 'Account the credential belongs to.';
COMMENT ON COLUMN iam.mfa_credential.credential_type IS 'totp / sms / email / recovery_codes.';
COMMENT ON COLUMN iam.mfa_credential.label IS 'User-facing label (phone tail, device name).';
COMMENT ON COLUMN iam.mfa_credential.secret_enc IS 'Shared secret / target (application-encrypted envelope; write-only through the API).';
COMMENT ON COLUMN iam.mfa_credential.verified_at IS 'When enrollment was proven with a valid code; unverified credentials are not usable.';
COMMENT ON COLUMN iam.mfa_credential.last_used_at IS 'Last successful use.';
COMMENT ON COLUMN iam.mfa_credential.is_active IS 'Whether usable at sign-in.';
COMMENT ON COLUMN iam.mfa_credential.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.mfa_credential.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.mfa_credential.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN iam.mfa_credential.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN iam.mfa_credential.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN iam.mfa_credential.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

CREATE TABLE iam.legacy_credential (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    algorithm varchar(30) NOT NULL,
    password_hash text NOT NULL,
    salt varchar(120),
    migrated_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_legacy_credential PRIMARY KEY (id),
    CONSTRAINT uq_legacy_credential_1 UNIQUE (user_id),
    CONSTRAINT ck_legacy_credential_algorithm CHECK (algorithm IN ('md5', 'sha1', 'sha256', 'bcrypt', 'phpass'))
);
COMMENT ON TABLE iam.legacy_credential IS 'Password hash imported from a system being migrated; verified once at first login, then re-hashed into user_account.password_hash and marked migrated.';
COMMENT ON COLUMN iam.legacy_credential.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.legacy_credential.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.legacy_credential.user_id IS 'Account the imported hash belongs to.';
COMMENT ON COLUMN iam.legacy_credential.algorithm IS 'Hash algorithm of the imported credential.';
COMMENT ON COLUMN iam.legacy_credential.password_hash IS 'Imported hash.';
COMMENT ON COLUMN iam.legacy_credential.salt IS 'Imported salt, when the algorithm needs one.';
COMMENT ON COLUMN iam.legacy_credential.migrated_at IS 'When the password was re-hashed into the modern scheme (NULL = still pending).';
COMMENT ON COLUMN iam.legacy_credential.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.legacy_credential.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.legacy_credential.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN iam.legacy_credential.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN iam.legacy_credential.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN iam.legacy_credential.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

ALTER TABLE iam.mfa_credential ADD CONSTRAINT fk_mfa_credential_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_mfa_credential_user_id ON iam.mfa_credential (user_id);
ALTER TABLE iam.legacy_credential ADD CONSTRAINT fk_legacy_credential_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE UNIQUE INDEX uq_user_role_assignment ON iam.user_role (user_id, role_id, scope_type, scope_id) NULLS NOT DISTINCT WHERE deleted_at IS NULL;

-- === P1-13: transactional outbox / inbox ===

CREATE TABLE iam.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    publish_error text,
    CONSTRAINT pk_iam_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE iam.outbox_event IS 'Transactional outbox of the iam module: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN iam.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN iam.outbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN iam.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN iam.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN iam.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN iam.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN iam.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
COMMENT ON COLUMN iam.outbox_event.publish_error IS 'Why the relay could not turn the row into an event (set aside, not published); NULL otherwise.';
CREATE INDEX ix_iam_outbox_event_pending ON iam.outbox_event (id) WHERE published_at IS NULL AND publish_error IS NULL;
CREATE TABLE iam.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_iam_inbox_event PRIMARY KEY (tenant_id, event_id)
);
COMMENT ON TABLE iam.inbox_event IS 'Inbox of the iam module: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN iam.inbox_event.event_id IS 'Global id of the consumed event; recorded per tenant.';
COMMENT ON COLUMN iam.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN iam.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN iam.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN iam.inbox_event.processing_error IS 'Last handling error, if any.';
CREATE INDEX ix_iam_inbox_event_processed ON iam.inbox_event (processed_at) WHERE processed_at IS NOT NULL;

-- === P1-15: business uniqueness ignores soft-deleted rows ===

